// Input: put your HTML string in $json.html (or adjust the key below)
const html = $input.first().json.data || '';

function htmlToText(input) {
  if (!input) return '';

  // 1) Remove script/style
  let s = input
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '');

  // 2) Preserve meaningful breaks before stripping tags
  //    - <a> => "text (url)"
  s = s.replace(/<a [^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, (m, url, text) => {
    // strip tags inside anchor text just in case
    const t = text.replace(/<\/?[^>]+>/g, '').trim();
    return t ? `${t} (${url})` : url;
  });

  //    - List bullets
  s = s.replace(/<li[^>]*>/gi, '• ');

  //    - Table cells and block ends -> separators
  s = s.replace(/<\/t[hd]>/gi, '\t')
       .replace(/<(br|\/p|\/div|\/li|\/h[1-6]|\/tr)>/gi, '\n');

  // 3) Strip the rest of the tags
  s = s.replace(/<\/?[^>]+>/g, '');

  // 4) Decode common HTML entities (basic, no external libs)
  s = s
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    // hex &#xHH;
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
    // decimal &#DDD;
    .replace(/&#(\d+);/g, (_, num) => String.fromCharCode(parseInt(num, 10)));

  // 5) Tidy whitespace
  s = s
    .replace(/\r/g, '')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  return s;
}

return [{ ...$json, text: htmlToText(html) }];

